settings.custom_css:
#single-course-materials .eb-accordion-item {
    background-color: rgb(101 101 101 / 0%);
    border-top: 1px solid #F2F2F2;
  border-radius: 0px;
    margin-bottom: 0px;
}
#single-course-materials .eb-accordion.border-b-1 .eb-accordion-item.active-item .eb-accordion-content {
    box-shadow: none;
}
#single-course-materials .eb-accordion-item {
  border-bottom: 1px solid #F2F2F2; 
}

#single-course-materials .eb-accordion.header-transparent-bg .eb-accordion-item .eb-accordion-header  {
      border-radius: 0px;
          border: none;
          font-size: 32px;
        padding: 33px 45px 33px 0px;
}

#single-course-materials .eb-accordion-item .eb-accordion-header, #single-course-materials .eb-accordion-item .eb-accordion-body {
    color: #F2F2F2;
     font-family: 'Libre Franklin';
}

#single-course-materials .eb-accordion-header.default-active.active, #single-course-materials .eb-accordion-item .eb-accordion-body, #single-course-materials .eb-accordion.header-transparent-bg .eb-accordion-item .eb-accordion-header.active {
        background-color: rgba(101, 101, 101, 0.0);
        font-family: 'Libre Franklin';
}

#single-course-materials .eb-accordion-header.default-active.active:before, #single-course-materials .eb-accordion-header:before {
    color: #F2F2F2;
    display: none;
}
#single-course-materials p { 
    flex: 1 1 40%;
}
#single-course-materials p a{
    display: flex;
    justify-content: center;
    align-items: center;
    width: 100%;
    padding: 13px 27px !important;

    font-family: "Libre Franklin", Sans-serif;
    font-size: 20px;
    font-weight: 600;
    line-height: 100%;
    fill: #FFF78D;
    color: #FFF78D;
    border-style: solid;
    border-width: 1px 1px 1px 1px;
    border-color: #FFF78D;
    border-radius: 0px 0px 0px 0px;
    padding: 17px 0px 17px 0px;
    border-bottom: 1px solid #FFF78D !important;
}
#single-course-materials p a:hover{
background-color: #f2f2f236;
}

#single-course-materials .learndash-wrapper.learndash-wrap.learndash-shortcode-wrap {
        margin-top: 10px;

    display: flex;
    flex-direction: row;
    gap: 20px;
    flex-wrap: wrap;
    align-content: center;
    justify-content: flex-start;  
}

 @media (max-width: 1025px) { 
     #single-course-materials p a {
    font-size: 16px;
    }
 }

 @media (max-width: 767px) {
#single-course-materials .learndash-wrapper.learndash-wrap.learndash-shortcode-wrap {
           justify-content: center;
}


 }
